-- This script runs automatically on first container initialization.

-- MISCONFIGURATION: Application user created with a trivially weak password
CREATE USER app_user WITH PASSWORD '123456';

-- MISCONFIGURATION: Second user with an equally weak, dictionary-based password
CREATE USER reporting_user WITH PASSWORD 'password';

-- MISCONFIGURATION: Broad privileges granted to the weakly-protected user
GRANT ALL PRIVILEGES ON DATABASE appdb TO app_user;
GRANT CONNECT ON DATABASE appdb TO reporting_user;

-- MISCONFIGURATION: Passwords are set to never expire; no rotation policy is enforced
ALTER USER app_user WITH VALID UNTIL 'infinity';
ALTER USER reporting_user WITH VALID UNTIL 'infinity';
